    91	
    92	    if (!egl.hasExtension(exts, "EGL_MESA_platform_surfaceless")) {
    93	        log.err("the EGL driver does not support EGL_MESA_platform_surfaceless " ++
    94	            "client extensions={s}", .{exts});
    95	        return;
    96	    }
    97	
    98	    log.err("the EGL driver rejected the surfaceless platform; " ++
    99	        "client extensions={s}", .{exts});
